Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"hidilyn":{"t":"Hidilyn Diaz’s Olympic journey","c":"Hidilyn Diaz is a Filipino weightlifter who won the Philippines’ first ever Olympic gold medal, at the Tokyo Olympics in 2021, in the women’s 55-kilogram class, setting an Olympic record. She grew up in Zamboanga City and began lifting with homemade weights of pipes and concrete. She had earlier won silver at the 2016 Rio Olympics, the first Olympic medal for a Filipina. She has competed at four Olympic Games.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1991</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Zamboanga City</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2008</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First Olympics, aged 17</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2016</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Silver medal in Rio de Janeiro</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2018</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Asian Games gold</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2021</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Olympic gold in Tokyo: a first for the Philippines</text></svg>","c":"From Zamboanga to Olympic gold"}]},"pacquiao":{"t":"Manny Pacquiao’s career","c":"Manny Pacquiao is a Filipino boxer and politician, the only boxer to have won world titles in eight different weight divisions. Born into poverty in Bukidnon, he left home as a teenager and turned professional at 16. Known as ‘Pacman’, he became one of the most famous athletes in Asia. He served as a congressman and a senator, ran for president in 2022, and returned to the ring in 2025.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1978</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Kibawe, Bukidnon</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1995</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Turns professional, aged 16</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1998</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First world title</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2010</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wins his eighth-division world title</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2016–22</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Serves as a senator</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2025</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Returns to boxing</text></svg>","c":"Key moments in his career"}]},"amorsolo":{"t":"Fernando Amorsolo’s life","c":"Fernando Amorsolo was a Filipino painter best known for sunlit scenes of rural life, rice planting and harvest, and portraits of Filipino women. He perfected a backlighting technique, painting figures glowing against bright sunlight. He also painted portraits, historical scenes and the destruction of Manila in the Second World War. In 1972, he was posthumously named the first National Artist of the Philippines.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1892</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Paco, Manila</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1914</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graduates from the University of the Philippines art school</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1920s–30s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Famous for sunlit rural scenes</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1940s</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paints wartime Manila</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ca8a04\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1972</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies; named first National Artist</text></svg>","c":"Key dates in Amorsolo’s life"}]},"phlit":{"t":"Landmarks of Philippine literature","c":"Philippine literature is written in many languages, including Filipino, English, Spanish and regional languages such as Cebuano and Ilocano. It began with oral traditions: epics, riddles, proverbs and songs. Spanish rule brought religious texts and metrical romances, and reformist writers in the 1880s used novels to call for change. In the American period, writing in English flourished. National Artists for Literature include Nick Joaquin, F. Sionil José and Bienvenido Lumbera.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Oral epics</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hudhud of the Ifugao; Darangen of the Maranao</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Florante at Laura, 1838</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Francisco Balagtas’s Tagalog romance</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Noli Me Tángere, 1887</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">José Rizal’s novel of colonial abuse</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Modern writing</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nick Joaquin, F. Sionil José and others</text></svg>","c":"Four landmarks"}]},"opm":{"t":"Original Pilipino Music through the years","c":"Original Pilipino Music, or OPM, means popular songs written and performed by Filipinos. The term took off in the 1970s with the ‘Manila Sound’ and singer-songwriters, and the Metro Manila Popular Music Festival, which produced hits such as ‘Anak’ by Freddie Aguilar. The 1990s saw a band explosion led by groups such as the Eraserheads. Since the 2010s, streaming has helped new singers and P-pop groups such as SB19 reach fans at home and abroad.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1970s</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Manila Sound and singer-songwriters</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1977</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Metro Manila Popular Music Festival begins</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1990s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The band explosion</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2010s</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Streaming brings new artists</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#db2777\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2020s</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">P-pop groups gain global fans</text></svg>","c":"OPM through the decades"}]},"phdance":{"t":"Some traditional Philippine dances","c":"Philippine music and dance reflect the country’s many cultures: Indigenous peoples of the Cordillera and Mindanao, Muslim communities of the south, and centuries of Spanish and American influence. Many folk dances were documented by Francisca Reyes Aquino from the 1920s. Traditional instruments include the kulintang, a row of gongs, the bamboo angklung and the rondalla string band. The Bayanihan Philippine National Folk Dance Company has performed around the world.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 306\" width=\"620\" height=\"306\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"600\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tinikling</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dancers step between clapping bamboo poles</text><rect x=\"10\" y=\"84\" width=\"600\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Singkil</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Maranao royal dance with fans and poles</text><rect x=\"10\" y=\"158\" width=\"600\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pandanggo sa Ilaw</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dancing with oil lamps balanced on head and hands</text><rect x=\"10\" y=\"232\" width=\"600\" height=\"64\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"260\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cariñosa</text><text x=\"24\" y=\"280\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A flirtatious dance with fan and handkerchief</text></svg>","c":"Four well-known folk dances"}]},"kundiman":{"t":"Facts about the kundiman","c":"The kundiman is a traditional Filipino love song, slow and melancholic, usually in a minor key that shifts to a major key in its second half. Many kundiman are songs of a lover’s devotion, but during the Spanish and American periods, some carried hidden patriotic messages, with the beloved standing for the motherland. Composers such as Francisco Santiago and Nicanor Abelardo turned it into an art song in the early 20th century. Famous examples include ‘Bayan Ko’ and ‘Nasaan Ka Irog’.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A love song</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Slow, tender and sorrowful</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Minor to major</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Often brightens in the second half</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hidden meanings</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The beloved can stand for the country</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Art songs</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Developed by Santiago and Abelardo</text></svg>","c":"Four features of the kundiman"}]},"phcinema":{"t":"Philippine cinema through the years","c":"Filipino films have been made since the early 20th century. The 1950s are remembered as a first golden age of big studios, and the 1970s and early 80s as a second, when directors such as Lino Brocka and Ishmael Bernal made films about poverty and injustice. Digital cameras and festivals such as Cinemalaya, from 2005, boosted independent cinema, and Filipino films and actors have since won awards at Cannes, Berlin and Venice.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1919</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dalagang Bukid: an early Filipino-made feature</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1950s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First golden age of the big studios</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1970s–80s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Second golden age: Brocka and Bernal</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2005</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cinemalaya festival boosts independent films</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2009</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brillante Mendoza wins best director at Cannes</text></svg>","c":"Key moments in Philippine film"}]},"zarzuela":{"t":"Facts about the sarswela","c":"The sarswela is a form of musical theatre that mixes spoken dialogue, songs and dance, adapted from the Spanish zarzuela in the late 19th century. Filipino writers and composers made it their own, writing in Tagalog and regional languages about love, family and social issues, and sometimes anti-colonial themes. It was the most popular entertainment in the early 1900s, until films took over. ‘Walang Sugat’ (1902) by Severino Reyes is one of the best-known works.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spanish roots</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From the zarzuela of Spain</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Songs and speech</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dialogue, music and dance together</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Local languages</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Written in Tagalog and regional languages</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Walang Sugat, 1902</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A famous sarswela by Severino Reyes</text></svg>","c":"Four features of the sarswela"}]},"phpower":{"t":"Where Philippine electricity comes from","c":"The Philippine power industry generates, transmits and distributes electricity across more than 7,600 islands, which makes building a single national grid difficult. Since 2001, generation has been run largely by private companies. Coal produces most of the electricity, followed by renewables and natural gas. The Philippines is one of the world’s leading producers of geothermal power, and solar and offshore wind are growing quickly. Electricity prices are among the highest in Southeast Asia. Shares are approximate for the early 2020s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 184\" width=\"620\" height=\"184\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"130\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Coal</text><rect x=\"140\" y=\"12\" width=\"330.0\" height=\"28\" rx=\"5\" fill=\"#475569\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 60%</text><text x=\"130\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Renewables</text><rect x=\"140\" y=\"52\" width=\"121.0\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"269\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 22% (geothermal, hydro, solar, wind)</text><text x=\"130\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Natural gas</text><rect x=\"140\" y=\"92\" width=\"82.5\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"230.5\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 15%</text><text x=\"130\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Oil</text><rect x=\"140\" y=\"132\" width=\"11.0\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"159\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2%</text></svg>","c":"Approximate share of electricity generated, early 2020s"}]},"japancountry":{"t":"The flag of Japan","c":"Japan’s flag is known as the Hinomaru, ‘circle of the sun’, reflecting the country’s name, Nihon, which means ‘origin of the sun’. A red disc on a white field, it has been used for centuries and was made official by law in 1999. Its simplicity has made it one of the world’s most recognisable flags.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/jp.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#d62828\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red disc: the sun</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"122\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: honesty and purity (popular</text><text x=\"312\" y=\"137\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">meaning)</text></svg>","c":"The flag and what its parts stand for"}]},"chinacountry":{"t":"The flag of China","c":"China’s flag, adopted in 1949 when the People’s Republic was founded, is called the Five-starred Red Flag. Red stands for the communist revolution. The large star represents the Communist Party, and the four smaller stars, which point towards it, the unity of the people around the party.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/cn.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#d62828\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the communist revolution</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#f6c90e\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"110\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large star: the Communist Party</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#f6c90e\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Four small stars: the people united</text></svg>","c":"The flag and what its parts stand for"}]},"indiacountry":{"t":"The flag of India","c":"India’s flag, the Tiranga (‘tricolour’), was adopted on 22 July 1947, shortly before independence. In the centre is the Ashoka Chakra, a navy-blue wheel with 24 spokes taken from the lion capital of Emperor Ashoka, representing the wheel of law and of progress. By law, the flag is meant to be made of khadi, hand-spun cloth.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/in.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ff9933\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Saffron: courage and sacrifice</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: peace and truth</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#138808\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: faith, growth and fertility</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#000080\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wheel: law and progress (24 spokes)</text></svg>","c":"The flag and what its parts stand for"}]},"indonesiacountry":{"t":"The flag of Indonesia","c":"Indonesia’s flag, called Sang Saka Merah Putih (the ‘sacred red and white’), was first raised when independence was declared on 17 August 1945. Its colours go back to the Majapahit Empire. It is almost identical to the flag of Monaco, differing only in its proportions.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/id.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#d62828\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: courage</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: purity</text></svg>","c":"The flag and what its parts stand for"}]},"pakistancountry":{"t":"The flag of Pakistan","c":"Pakistan’s flag was adopted just before independence in August 1947. The dark green field stands for the country’s Muslim majority and the white stripe for its religious minorities. The crescent represents progress and the star light and knowledge.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/pk.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#01411c\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: the Muslim majority</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: religious minorities</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crescent: progress</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Star: light and knowledge</text></svg>","c":"The flag and what its parts stand for"}]},"vietnamcountry":{"t":"The flag of Vietnam","c":"Vietnam’s flag, a yellow star on a red field, was first used by the Viet Minh independence movement in 1940 and became the flag of the whole country after reunification in 1976. The five points of the star are said to represent workers, farmers, intellectuals, young people and soldiers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/vn.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#da251d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: revolution and sacrifice</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffcd00\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"122\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Star’s five points: the five</text><text x=\"312\" y=\"137\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">groups of society</text></svg>","c":"The flag and what its parts stand for"}]},"southkoreacountry":{"t":"The flag of South Korea","c":"South Korea’s flag, the Taegukgi, has a red and blue taegeuk at its centre, representing the balance of opposites, yin and yang. Around it are four black trigrams from the I Ching, standing for heaven, earth, water and fire. It was first used in the 1880s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/kr.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: peace and purity</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#cd2e3a\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"102\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red and blue taegeuk: balance of</text><text x=\"312\" y=\"117\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">opposites</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"142\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Four trigrams: heaven, earth,</text><text x=\"312\" y=\"157\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">water, fire</text></svg>","c":"The flag and what its parts stand for"}]},"irancountry":{"t":"The flag of Iran","c":"Iran’s current flag was adopted in 1980, after the Islamic Revolution. The red emblem in the centre is a stylised form of the word ‘Allah’. Along the edges of the green and red stripes, the phrase ‘Allahu akbar’ (‘God is great’) is written 22 times in Kufic script, marking the date of the revolution, 22 Bahman in the Iranian calendar.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/ir.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#239f40\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: Islam and growth</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: peace</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#da0000\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: courage and martyrdom</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#da0000\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Emblem: a stylised ‘Allah’</text></svg>","c":"The flag and what its parts stand for"}]},"turkeycountry":{"t":"The flag of Türkiye","c":"Türkiye’s flag, called Ay Yıldız (‘moon star’), shows a white crescent and star on red. Its design comes from the late Ottoman Empire, and its exact proportions were fixed by law in 1936. Popular legends link the image to the reflection of the moon and a star in pools of soldiers’ blood after a battle.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/tr.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#e30a17\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"82\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: often linked to the blood of</text><text x=\"312\" y=\"97\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">martyrs</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"122\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crescent and star: long-used</text><text x=\"312\" y=\"137\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">symbols of the land</text></svg>","c":"The flag and what its parts stand for"}]},"saudicountry":{"t":"The flag of Saudi Arabia","c":"Saudi Arabia’s flag carries the Shahada, the Islamic declaration of faith: ‘There is no god but God; Muhammad is the Messenger of God’, above a sword. Because it contains a holy text, it is never flown at half-mast, and it is made so that the writing reads correctly from both sides.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/sa.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#006c35\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: Islam</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"102\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Writing: the Shahada, declaration</text><text x=\"312\" y=\"117\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">of faith</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sword: justice and strength</text></svg>","c":"The flag and what its parts stand for"}]},"thailandcountry":{"t":"The flag of Thailand","c":"Thailand’s flag, the Trairanga (‘tricolour’), was adopted in 1917 by King Vajiravudh. Its five horizontal stripes of red, white and blue, with a wide blue band in the middle, represent the nation, religion and monarchy, the three pillars of Thai identity.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/th.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#a51931\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the nation (land and people)</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"110\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: religion</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#2d2a4a\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue: the monarchy</text></svg>","c":"The flag and what its parts stand for"}]},"malaysiacountry":{"t":"The flag of Malaysia","c":"Malaysia’s flag is called the Jalur Gemilang, ‘stripes of glory’. Its 14 red and white stripes and the 14-pointed star stand for the equal status of the 13 states and the federal government. The crescent represents Islam, the official religion, and yellow is the royal colour of the Malay rulers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/my.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#cc0001\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"42\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">14 stripes: the 13 states and</text><text x=\"312\" y=\"57\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">federal government</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#010066\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue: unity of the people</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffcc00\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crescent: Islam</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffcc00\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"162\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">14-pointed star: unity; yellow is</text><text x=\"312\" y=\"177\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">royal</text></svg>","c":"The flag and what its parts stand for"}]},"singaporecountry":{"t":"The flag of Singapore","c":"Singapore’s flag was adopted in 1959, when it became self-governing, and kept at independence in 1965. The crescent moon represents a young nation on the rise, and its five stars stand for the nation’s ideals: democracy, peace, progress, justice and equality.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/sg.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ef3340\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"42\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: universal brotherhood and</text><text x=\"312\" y=\"57\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">equality</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: purity and virtue</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crescent: a young nation on the rise</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Five stars: five national ideals</text></svg>","c":"The flag and what its parts stand for"}]},"myanmarcountry":{"t":"The flag of Myanmar","c":"Myanmar’s current flag was introduced in 2010, along with a new constitution. Its three horizontal stripes of yellow, green and red carry a large white five-pointed star in the centre, representing the union of the country.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/mm.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#fecb00\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yellow: solidarity</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#34b233\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: peace and the green land</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ea2839\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: courage and determination</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White star: the union</text></svg>","c":"The flag and what its parts stand for"}]},"cambodiacountry":{"t":"The flag of Cambodia","c":"Cambodia’s flag shows the temple of Angkor Wat in white on a red band between two blue stripes, making it one of very few national flags to feature a building. Versions of the flag with Angkor Wat have been used since the 1850s, and the current flag was restored in 1993 along with the monarchy.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/kh.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#032ea1\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue: the monarchy</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#e00025\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"110\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the nation</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Angkor Wat: religion and heritage</text></svg>","c":"The flag and what its parts stand for"}]},"laoscountry":{"t":"The flag of Laos","c":"The flag of Laos was first used by the Lao independence movement in the 1940s and became the national flag in 1975. The white disc is said to represent the full moon over the Mekong River, and also the unity of the people under the government.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/la.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ce1126\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the blood shed for freedom</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#002868\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"102\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue: the Mekong and the nation’s</text><text x=\"312\" y=\"117\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">wealth</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White disc: the full moon, and unity</text></svg>","c":"The flag and what its parts stand for"}]},"bruneicountry":{"t":"The flag of Brunei","c":"Brunei’s flag has a yellow field, the colour of the sultan, crossed by diagonal white and black stripes representing his chief ministers. In the centre is the national crest in red, with an umbrella, wings, hands and a crescent, inscribed with the national motto in Arabic script: ‘Always in service with God’s guidance’.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/bn.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#f7e017\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yellow: the sultan</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"102\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White and black stripes: chief</text><text x=\"312\" y=\"117\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">ministers</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#cf1126\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crest: the state and Islam</text></svg>","c":"The flag and what its parts stand for"}]},"timorlestecountry":{"t":"The flag of Timor-Leste","c":"Timor-Leste’s flag was first raised in 1975 and again at the restoration of independence on 20 May 2002. Its colours tell the story of the country’s struggle: a black triangle over a yellow arrowhead on a red field, with a white star as a guiding light.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/tl.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#dc241f\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the struggle for liberation</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffc726\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yellow: traces of colonialism</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black: hardships to be overcome</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White star: hope and peace</text></svg>","c":"The flag and what its parts stand for"}]},"bangladeshcountry":{"t":"The flag of Bangladesh","c":"Bangladesh’s flag, adopted in 1972, shows a red disc on a dark green field. The disc is set slightly towards the hoist, so it appears centred when the flag flies. The red represents the sun rising over Bengal and the blood of those who died in the 1971 Liberation War.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/bd.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#006a4e\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: the land and its vitality</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#f42a41\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"122\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red disc: the rising sun and the</text><text x=\"312\" y=\"137\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">sacrifice of 1971</text></svg>","c":"The flag and what its parts stand for"}]},"israelcountry":{"t":"The flag of Israel","c":"Israel’s flag, adopted in 1948, shows a blue Star of David, an ancient Jewish symbol, between two blue stripes on white. The design is based on the tallit, the Jewish prayer shawl, which is white with blue or black stripes.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/il.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"52\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#0038b8\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"70\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue stripes: a Jewish prayer shawl</text><rect x=\"276\" y=\"92\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#0038b8\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"110\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Star of David: a Jewish symbol</text><rect x=\"276\" y=\"132\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"150\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White background</text></svg>","c":"The flag and what its parts stand for"}]},"uaecountry":{"t":"The flag of the United Arab Emirates","c":"The flag of the United Arab Emirates was adopted on 2 December 1971, when the federation was formed. Its red, green, white and black are the Pan-Arab colours, used in the flags of many Arab countries and linked to the Arab Revolt against Ottoman rule in 1916.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/ae.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ef3340\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the Pan-Arab colours</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#00843d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black</text></svg>","c":"The flag and what its parts stand for"}]},"iraqcountry":{"t":"The flag of Iraq","c":"Iraq’s flag uses the Pan-Arab colours red, white and black. Since 2008, the green words in the centre have been the takbir, ‘Allahu akbar’ (‘God is great’), written in Kufic script. The three green stars of earlier versions were removed at that time.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/iq.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ce1126\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: courage</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: generosity</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black: past hardship</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#007a3d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green writing: ‘God is great’</text></svg>","c":"The flag and what its parts stand for"}]},"jordancountry":{"t":"The flag of Jordan","c":"Jordan’s flag is based on the flag of the Arab Revolt of 1916. Its three stripes stand for three historic Arab caliphates, and the red triangle for the ruling Hashemite family. The white seven-pointed star represents the seven verses of the opening chapter of the Qur’an, and the unity of Arab peoples.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/jo.svg\" x=\"10\" y=\"22\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"22\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"18\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"36\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black: the Abbasid Caliphate</text><rect x=\"276\" y=\"58\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"76\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: the Umayyad Caliphate</text><rect x=\"276\" y=\"98\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#007a3d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"116\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: the Fatimid Caliphate</text><rect x=\"276\" y=\"138\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ce1126\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"156\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red triangle: the Hashemite dynasty</text><rect x=\"276\" y=\"178\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"188\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Seven-pointed star: the Qur’an’s</text><text x=\"312\" y=\"203\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">first chapter</text></svg>","c":"The flag and what its parts stand for"}]},"nigeriacountry":{"t":"The flag of Nigeria","c":"Nigeria’s flag was designed in 1959 by Michael Taiwo Akinkunmi, a student, who won a national competition. It was first raised at independence on 1 October 1960. Its three vertical bands are green, white and green.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/ng.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#008751\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: forests and natural wealth</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: peace and unity</text></svg>","c":"The flag and what its parts stand for"}]},"egyptcountry":{"t":"The flag of Egypt","c":"Egypt’s flag has red, white and black horizontal stripes, the colours of the Arab Liberation flag used after the 1952 revolution. In the centre is the Eagle of Saladin in gold, holding a scroll with the country’s name in Arabic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/eg.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ce1126\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: struggle and sacrifice</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: the peaceful 1952 revolution</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black: the end of oppression</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#c09300\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"162\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Eagle of Saladin: the national</text><text x=\"312\" y=\"177\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">emblem</text></svg>","c":"The flag and what its parts stand for"}]},"southafricacountry":{"t":"The flag of South Africa","c":"South Africa’s flag was adopted in 1994, when apartheid ended and the country held its first democratic elections. Its six colours have no official meanings, but the Y shape is widely seen as the coming together of the country’s different peoples, taking the road ahead in unity.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/za.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#007a4d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"42\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Y shape: diverse peoples coming</text><text x=\"312\" y=\"57\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">together</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black, green and gold</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#de3831\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red, white and blue</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffb612\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"170\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">No official meanings for the colours</text></svg>","c":"The flag and what its parts stand for"}]},"ethiopiacountry":{"t":"The flag of Ethiopia","c":"Ethiopia’s green, yellow and red were adopted in the 1890s, and because Ethiopia was never colonised, they inspired many other African flags, becoming the Pan-African colours. The blue disc with a yellow star was added in 1996.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/et.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"32\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#078930\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"50\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: the land and hope</text><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#fcdd09\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yellow: peace and harmony</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#da121a\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: strength and sacrifice</text><rect x=\"276\" y=\"152\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#0f47af\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"162\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue disc and star: unity and</text><text x=\"312\" y=\"177\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">equality</text></svg>","c":"The flag and what its parts stand for"}]},"kenyacountry":{"t":"The flag of Kenya","c":"Kenya’s flag was adopted at independence on 12 December 1963 and is based on the flag of the Kenya African National Union. In the centre is a traditional Maasai shield with two crossed spears, symbolising the defence of freedom.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/ke.svg\" x=\"10\" y=\"22\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"22\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"18\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#111111\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"36\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Black: the people</text><rect x=\"276\" y=\"58\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#bb0000\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"76\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the blood shed for independence</text><rect x=\"276\" y=\"98\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#006600\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"116\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green: the land and its wealth</text><rect x=\"276\" y=\"138\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#ffffff\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"156\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">White: peace</text><rect x=\"276\" y=\"178\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#bb0000\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"196\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shield and spears: defending freedom</text></svg>","c":"The flag and what its parts stand for"}]},"moroccocountry":{"t":"The flag of Morocco","c":"Morocco’s flag is red, the traditional colour of the ruling Alaouite dynasty, with a green interlaced five-pointed star in the centre. The star, known as the Seal of Solomon, was added in 1915. Its five points are often linked to the five pillars of Islam.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 212\" width=\"620\" height=\"212\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><image href=\"flags/ma.svg\" x=\"10\" y=\"16\" width=\"240\" height=\"180\" preserveAspectRatio=\"none\"/><rect x=\"10\" y=\"16\" width=\"240\" height=\"180\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".35\"/><rect x=\"276\" y=\"72\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#c1272d\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"90\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Red: the royal Alaouite dynasty</text><rect x=\"276\" y=\"112\" width=\"26\" height=\"26\" rx=\"5\" fill=\"#006233\" stroke=\"currentColor\" stroke-opacity=\".4\"/><text x=\"312\" y=\"130\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Green star: the Seal of Solomon</text></svg>","c":"The flag and what its parts stand for"}]}});
